    payload={'csrf':csrf(actor,'/laventanita/catalogo?sucursal=principal'),'tenant':tenant,'branch_id':branch,'guest_name':name,'guest_phone':phone,'delivery_type':'coordinated','address':'Dirección ficticia R11','payment':'Efectivo','checkout_key':secrets.token_hex(16),'items':[{'id':pid,'qty':quantity,'option_ids':[]}]}
    args=['docker','exec','-i','fisitaap-r2-web','curl','--noproxy','*','-sS','-b','/tmp/r3-'+actor+'.cookies','-c','/tmp/r3-'+actor+'.cookies','-H','Content-Type: application/json','--data-binary','@-','-w','\n%{http_code}','http://localhost/api/checkout'];p=subprocess.run(args,input=json.dumps(payload).encode(),capture_output=True,check=True);body,status=p.stdout.rsplit(b'\n',1);return int(status),json.loads(body)
